  'The course is structured as a 15-week semester. It begins with foundations and methods, moves through major theories and modern evidence, then ends with culture, development, relationships, applied outcomes, personality pathology, and a capstone evidence portfolio.',
  $persjson${"slug": "personality-psychology", "title": "Personality Psychology", "description": "The course is structured as a 15-week semester. It begins with foundations and methods, moves through major theories and modern evidence, then ends with culture, development, relationships, applied outcomes, personality pathology, and a capstone evidence portfolio.", "topics": [{"id": "3d280093-b5dd-4c16-87e1-60a6da3ce3fd", "type": "topic", "title": "Foundations of Personality Science", "description": "This unit defines personality as patterned individuality: stable yet developing ways people think, feel, strive, relate, and adapt across contexts.", "children": [{"id": "bba625f7-28e1-4579-9359-0a0643408fd1", "type": "subtopic", "title": "Personality as a scientific construct", "children": [{"id": "354cdee8-e33d-4a5a-b087-7d91a3a3b40b", "type": "concept", "title": "traits and states"}, {"id": "132c4455-c3c6-4584-9d62-69eb26b5fd39", "type": "concept", "title": "individual differences"}, {"id": "ac0fc9b1-1198-40c8-98dd-e9ce859af479", "type": "concept", "title": "within-person variability"}, {"id": "6e4a9131-f15b-46ce-84a5-c70cf99f0f05", "type": "concept", "title": "prediction and explanation"}], "description": "Students learn what personality explains and how it differs from mood, identity, values, and psychopathology."}, {"id": "68c6abd2-4630-4e19-b702-7f9d15f10d34", "type": "subtopic", "title": "Major questions in the field", "children": [{"id": "57e760c7-12cd-4fe9-90db-5d2202d8de57", "type": "concept", "title": "consistency versus change"}, {"id": "134bf15d-20ac-4a7e-bd9c-dd82d7426e88", "type": "concept", "title": "person versus situation"}, {"id": "21d51336-acbf-449d-bc51-deaa24cfc538", "type": "concept", "title": "nature and nurture"}, {"id": "3ccb69b3-e19e-4b32-930f-63f31798a193", "type": "concept", "title": "universals and culture"}], "description": "Students learn the enduring debates that organize personality psychology."}, {"id": "dba8247e-7cf3-476c-a4a8-ec42fecdad1a", "type": "subtopic", "title": "History of personality psychology", "children": [{"id": "7e0841c0-0474-4f82-9fe9-99fc23263677", "type": "concept", "title": "case traditions"}, {"id": "e5b1275a-ae9d-4c52-be97-5997ed9f46cc", "type": "concept", "title": "psychometric tradition"}, {"id": "876f493f-7bd3-4046-a3a3-14f421555a62", "type": "concept", "title": "humanistic reaction"}, {"id": "a772034b-6c50-411e-9df4-68f4c3d6c486", "type": "concept", "title": "contemporary integrative models"}], "description": "Students see how clinical, social, biological, and measurement traditions shaped the modern field."}]}, {"id": "fe773225-d84c-4a10-94c0-4511c4722b05", "type": "topic", "title": "Research Methods, Statistics, and Open Science in Personality", "description": "Personality claims require careful design because the field relies heavily on self-report, longitudinal data, observer reports, and correlational inference.", "children": [{"id": "3329b2d2-609d-458e-bd4a-032335f8eb2e", "type": "subtopic", "title": "Designs for personality research", "children": [{"id": "2ef7a081-4991-491d-8190-3fae948694ed", "type": "concept", "title": "nomothetic and idiographic methods"}, {"id": "d540a195-c96d-4cd1-bddc-56a9907ce82e", "type": "concept", "title": "daily diary methods"}, {"id": "63ff56de-6254-4bef-acd5-b993173f97bc", "type": "concept", "title": "multi-method assessment"}, {"id": "1e92fbff-6c54-4621-b108-ae845c5280a7", "type": "concept", "title": "longitudinal panels"}], "description": "Students compare cross-sectional, longitudinal, experience-sampling, experimental, behavioral, and informant designs."}, {"id": "e7910de9-f8fc-4f1f-b702-5f162d8146f7", "type": "subtopic", "title": "Statistical reasoning", "children": [{"id": "aba7869e-d85f-4a6c-8e1a-37205f31e1e7", "type": "concept", "title": "correlation"}, {"id": "995473f7-a711-4543-9363-6fba67bd06cf", "type": "concept", "title": "multiple regression"}, {"id": "bb46932d-6ce9-403a-80c0-3fd042ab7760", "type": "concept", "title": "factor analysis"}, {"id": "60715a01-9f80-4688-a439-d93335e45548", "type": "concept", "title": "effect size"}, {"id": "80645828-1f6e-4ed4-8282-f681eac1246d", "type": "concept", "title": "power"}], "description": "Students learn how correlation, regression, factor analysis, and effect sizes support personality evidence."}, {"id": "176f8d98-b661-4ca7-a320-f277c9154714", "type": "subtopic", "title": "Open science and replication", "children": [{"id": "c357ad8f-c85d-4062-8366-4f5e0f464ec6", "type": "concept", "title": "preregistration"}, {"id": "8b0e2e5a-120f-46ec-9d2b-7824fde427c0", "type": "concept", "title": "registered reports"}, {"id": "8399594e-84d1-4000-80d1-e66d7f6e9acf", "type": "concept", "title": "open materials"}, {"id": "c08f4e5c-3f5a-4d6a-89f1-0d41342500e3", "type": "concept", "title": "replication"}, {"id": "14d1f36e-577f-43ca-bf47-46493bf74a23", "type": "concept", "title": "meta-analysis"}], "description": "Students learn why transparent methods matter for personality and social-personality research."}]}, {"id": "559bb7c3-4e8d-4694-b53c-2f47c9661e1b", "type": "topic", "title": "Trait Theory and the Big Five", "description": "Trait approaches give students the dominant language for describing broad, measurable dimensions of personality.", "children": [{"id": "5f59dbdf-c95f-4188-a098-6b47aaf2cd53", "type": "subtopic", "title": "Lexical and factor-analytic foundations", "children": [{"id": "13ce1637-7662-48cc-b1dc-afc8f90d16d3", "type": "concept", "title": "lexical hypothesis"}, {"id": "668e068d-5663-4571-b5ed-455a5782daf7", "type": "concept", "title": "factor extraction"}, {"id": "62fd6986-0102-4fae-89cd-7aea6a9a7ca7", "type": "concept", "title": "rotation"}, {"id": "29d8feda-8d07-4f99-936f-e75648091d86", "type": "concept", "title": "hierarchical traits"}], "description": "Students learn how trait taxonomies emerged from language and statistical structure."}, {"id": "fae0f0d3-40d4-4b40-af8e-c433c76e80cf", "type": "subtopic", "title": "Big Five and HEXACO models", "children": [{"id": "292a7ea5-ef2a-415a-bdb9-3df59e98d201", "type": "concept", "title": "openness"}, {"id": "52aeaf51-a7b5-4f4a-914b-0add822d7549", "type": "concept", "title": "conscientiousness"}, {"id": "314c8ded-32d5-4828-9d15-61ebb99c1d29", "type": "concept", "title": "extraversion"}, {"id": "5c7a2333-2fed-41b6-9bbf-6bbd21335c68", "type": "concept", "title": "agreeableness"}, {"id": "88171b9a-634e-4a96-bec1-2ec0a8264993", "type": "concept", "title": "neuroticism"}, {"id": "474cd81f-07e7-4b3b-b4d5-39958f94fd3a", "type": "concept", "title": "honesty-humility"}], "description": "Students compare major trait frameworks and what each adds."}, {"id": "89ad3739-8631-47a5-bb26-bdcc6da97cd5", "type": "subtopic", "title": "Trait prediction", "children": [{"id": "1c3179d0-9b53-4ed1-b139-adfa2b65b165", "type": "concept", "title": "academic outcomes"}, {"id": "465beb03-92d5-4f3a-8c2d-aea9a29e66de", "type": "concept", "title": "work performance"}, {"id": "fab7e54a-449b-43e4-a6c0-69c9ac680534", "type": "concept", "title": "relationships"}, {"id": "6b06be1b-f6f7-4af3-b997-425ae0ffd1ba", "type": "concept", "title": "health behavior"}], "description": "Students learn when traits predict life outcomes and when context matters."}]}, {"id": "0c66027a-d849-4dfc-897b-697645966aae", "type": "topic", "title": "Psychodynamic and Neo-Analytic Theories", "description": "This unit treats psychodynamic traditions as historically important theories of motivation, conflict, defense, attachment, and narrative meaning.", "children": [{"id": "8192b325-4629-4b60-9cdf-ad5e8b847037", "type": "subtopic", "title": "Freudian theory", "children": [{"id": "cd02d083-1a25-40cb-97be-08d8f3bc0195", "type": "concept", "title": "unconscious motivation"}, {"id": "e03d5a71-af36-463a-96ee-6c2710efd2e9", "type": "concept", "title": "id/ego/superego"}, {"id": "82d85726-c360-4d3b-9c79-1147567a0c55", "type": "concept", "title": "defense mechanisms"}, {"id": "92356306-0d4b-43b1-9c73-72f1f45dfdb0", "type": "concept", "title": "psychosexual stages"}], "description": "Students learn the core ideas and limits of classical psychoanalytic theory."}, {"id": "1c84229e-25e6-4f01-862e-c36497c241a0", "type": "subtopic", "title": "Neo-analytic perspectives", "children": [{"id": "30db98f8-90ab-40a8-98cd-706cf5d84634", "type": "concept", "title": "Jung"}, {"id": "cdbe962e-e49a-4ffb-ad7c-bb42e0160a06", "type": "concept", "title": "Adler"}, {"id": "db058dee-2efd-439e-8a05-42fca573480f", "type": "concept", "title": "Horney"}, {"id": "c08f8bea-293c-4233-a2d1-9f4fbe148882", "type": "concept", "title": "Erikson"}, {"id": "374b2a9e-03de-48f1-b439-a30cf37d778d", "type": "concept", "title": "object relations"}], "description": "Students examine how later theorists revised psychoanalysis toward social, cultural, and developmental themes."}, {"id": "de3a7a99-3818-42cb-a74c-0733f9f3dbb9", "type": "subtopic", "title": "Modern relevance", "children": [{"id": "276352c3-1b5d-4856-bf66-35dc2f6eb519", "type": "concept", "title": "defensive processing"}, {"id": "1692021f-0d97-473a-9c34-0d660ccc191f", "type": "concept", "title": "implicit motives"}, {"id": "2f39c91c-e433-478f-a856-f2e087bcd588", "type": "concept", "title": "attachment"}, {"id": "17d6a847-89b7-4dfa-92ea-156f8a88ceba", "type": "concept", "title": "narrative identity"}], "description": "Students distinguish unsupported historical claims from enduring ideas that influenced clinical and personality research."}]}, {"id": "721edf13-133c-46f9-a6f5-b8aed998f0ae", "type": "topic", "title": "Humanistic, Existential, and Positive Personality Approaches", "description": "Humanistic and existential approaches emphasize agency, meaning, growth, authenticity, and the person's subjective experience.", "children": [{"id": "6a5d6ec7-36a1-4dd4-b303-f686357105d0", "type": "subtopic", "title": "Humanistic theories", "children": [{"id": "348492b3-a410-4a73-91a3-a2456650531a", "type": "concept", "title": "self-actualization"}, {"id": "a94b3a35-f521-41f5-ac02-edd627aa4f30", "type": "concept", "title": "unconditional positive regard"}, {"id": "e97a9abb-e884-4756-a655-324e09258be4", "type": "concept", "title": "congruence"}, {"id": "caf2b40b-0825-4570-8136-65df495b06e3", "type": "concept", "title": "growth mindset links"}], "description": "Students learn how Rogers and Maslow shifted attention toward self-concept, growth, and conditions for flourishing."}, {"id": "10a44490-ffdc-418f-b006-5df2dfaee26b", "type": "subtopic", "title": "Existential themes", "children": [{"id": "4466e074-4bdc-47bb-88c3-70533f1bd460", "type": "concept", "title": "meaning-making"}, {"id": "59e2b3ea-da43-4ccc-a33c-1601c76feb74", "type": "concept", "title": "choice"}, {"id": "57f695a2-c8c9-48de-bc1e-ff6023c26480", "type": "concept", "title": "anxiety"}, {"id": "ef58d67a-dea9-4f62-a9c4-c6f18ab49707", "type": "concept", "title": "authenticity"}], "description": "Students examine meaning, freedom, responsibility, mortality, and authenticity as personality concerns."}, {"id": "bec92b01-d7ab-4f69-8fae-e3a63d8f7600", "type": "subtopic", "title": "Positive personality science", "children": [{"id": "9034e09d-c128-4e40-b381-1e7c125f3bd9", "type": "concept", "title": "character strengths"}, {"id": "c4fe118f-08a6-49af-b33c-2bbe56f487d6", "type": "concept", "title": "gratitude"}, {"id": "160601b6-d150-42a5-9ea9-e2577d068562", "type": "concept", "title": "optimism"}, {"id": "dcdbd1b4-cb37-4760-9dca-d4d10eeb17cd", "type": "concept", "title": "resilience"}], "description": "Students connect strengths, virtues, well-being, and resilience to empirical research."}]}, {"id": "64ebf699-e849-4721-aa39-8d9ab8759b88", "type": "topic", "title": "Social-Cognitive, Learning, and Behavioral Approaches", "description": "This unit shows how personality is expressed through learned patterns, beliefs, goals, expectancies, and situation-specific behavior.", "children": [{"id": "209352a3-d1c7-41e3-b9cc-470689d10bcf", "type": "subtopic", "title": "Learning traditions", "children": [{"id": "dd0d0e91-2fc8-4e5f-8784-3d04f41cd53c", "type": "concept", "title": "conditioning"}, {"id": "d48d74a2-f138-4de1-83b1-a2706cd9c3db", "type": "concept", "title": "reinforcement"}, {"id": "9657fb8d-c70a-4820-942d-7d3832fdaa30", "type": "concept", "title": "observational learning"}, {"id": "4dea0f2b-9e09-4970-94c9-a499e5ab4a03", "type": "concept", "title": "behavioral consistency"}], "description": "Students connect behaviorism and social learning to personality development."}, {"id": "fb9d6095-1601-4ac8-861d-e1ab5d851147", "type": "subtopic", "title": "Social-cognitive theory", "children": [{"id": "9a34d8da-cbd0-490b-884c-825d9e228e8d", "type": "concept", "title": "reciprocal determinism"}, {"id": "74160aee-5d58-414d-8152-a23b59eda676", "type": "concept", "title": "self-efficacy"}, {"id": "c14c71d1-bbe5-4b7e-aea5-1220ab5b5dc0", "type": "concept", "title": "expectancies"}, {"id": "cdc09765-a3cf-4a55-8ee0-e3230f8cba79", "type": "concept", "title": "competencies"}], "description": "Students learn how beliefs and goals organize behavior."}, {"id": "2ebbb5e2-f5c1-4c6e-a74e-61575538aed1", "type": "subtopic", "title": "Person-situation interaction", "children": [{"id": "d45efe90-e4e3-48d5-8133-218eb69ae334", "type": "concept", "title": "Mischel critique"}, {"id": "ff76cc43-5297-4fdf-842b-58b5b6fca6ac", "type": "concept", "title": "behavioral signatures"}, {"id": "650e90f9-b2c4-4424-872e-4b77aa4581f2", "type": "concept", "title": "situation strength"}, {"id": "f7a94ad8-c3e3-4126-87a9-27b0aafef2ed", "type": "concept", "title": "interactionism"}], "description": "Students learn to think of personality as patterns of if-then responses across contexts."}]}, {"id": "5ab76fd7-f2fd-46dc-910f-d61c995b17b6", "type": "topic", "title": "Biological, Genetic, and Evolutionary Foundations", "description": "Personality is partly rooted in biological systems, but biological explanations must be handled carefully and probabilistically.", "children": [{"id": "ebaefa03-c701-4840-a938-e6ddc30d5895", "type": "subtopic", "title": "Behavior genetics", "children": [{"id": "f36976be-a54a-47ea-aec8-4b5f1b664e06", "type": "concept", "title": "twin studies"}, {"id": "85f14d6d-f973-4b65-84c9-33228d7969af", "type": "concept", "title": "adoption studies"}, {"id": "d2e0ce1e-ca3a-4d20-947a-55870fe67153", "type": "concept", "title": "heritability"}, {"id": "5abfe4b1-6723-4fc9-ac1c-3e0df007d47d", "type": "concept", "title": "gene-environment correlation"}], "description": "Students learn what heritability means and what it does not mean."}, {"id": "51a454f6-d255-4095-aff6-0ffd91816154", "type": "subtopic", "title": "Temperament and neuroscience", "children": [{"id": "c97cd3e2-160e-44f9-aa59-96f5c20b0f2f", "type": "concept", "title": "reactivity"}, {"id": "0ff7337c-ce0b-42af-9e67-073527e14c4d", "type": "concept", "title": "self-regulation"}, {"id": "971a493d-e729-4c9e-b17c-0f842b40998d", "type": "concept", "title": "reward sensitivity"}, {"id": "de75dd1f-061e-479f-bfb1-e9cf31ecb2a5", "type": "concept", "title": "threat sensitivity"}], "description": "Students connect early temperament and neural systems to adult personality tendencies."}, {"id": "ebf25853-2b1f-4740-96bf-841f238cfe9b", "type": "subtopic", "title": "Evolutionary perspectives", "children": [{"id": "2ddb7a87-2644-47de-9f9d-e3ca465af9b4", "type": "concept", "title": "life history"}, {"id": "411a91d2-80eb-47d7-a1b5-ac1b530bbdf7", "type": "concept", "title": "mate preferences"}, {"id": "e2ade14c-d3b9-4dc4-aa22-01f53fd5a17c", "type": "concept", "title": "status strategies"}, {"id": "5014ee91-6c69-4461-8de9-d4729ca65695", "type": "concept", "title": "costly tradeoffs"}], "description": "Students evaluate adaptive explanations for individual differences."}]}, {"id": "78684102-c4a2-4d1c-b182-c2f96173c3bb", "type": "topic", "title": "Self, Identity, Motivation, and Narrative", "description": "This unit links trait structure to the stories people tell about who they are, what they value, and where their lives are going.", "children": [{"id": "413c56bc-a485-461b-8a9a-34ba67028b52", "type": "subtopic", "title": "Self-concept and identity", "children": [{"id": "9c11e4dd-6f81-4c09-bb7c-228976f52eae", "type": "concept", "title": "self-schema"}, {"id": "90204357-5d24-44f0-b291-bc23e3ccc2d8", "type": "concept", "title": "possible selves"}, {"id": "4ed9d05b-1663-4565-8aa7-a588e0d47660", "type": "concept", "title": "identity status"}, {"id": "c2e02f5e-fe72-4cfc-a5dd-1715265aff3d", "type": "concept", "title": "self-esteem"}], "description": "Students study how people represent themselves across roles, groups, and time."}, {"id": "b2c18150-26df-4d53-9cb0-816aaf61386c", "type": "subtopic", "title": "Motives and goals", "children": [{"id": "8c7eeb3c-90b5-4124-94d4-3ccf7a42e4ff", "type": "concept", "title": "achievement motive"}, {"id": "313e2eab-3b09-4eae-a684-ae1699e2689b", "type": "concept", "title": "affiliation motive"}, {"id": "7bdcf40c-f8ae-4bf1-bdaf-d7bb1a734618", "type": "concept", "title": "power motive"}, {"id": "a3ea7e54-d03e-4393-bae6-6258751b065e", "type": "concept", "title": "personal strivings"}], "description": "Students learn how needs, values, goals, and implicit motives shape personality expression."}, {"id": "bac5122f-8fc4-4586-894c-91a073fc1198", "type": "subtopic", "title": "Narrative identity", "children": [{"id": "80420237-706b-415f-b752-fa6db6b715f0", "type": "concept", "title": "redemption sequences"}, {"id": "53396f09-2346-4857-808a-5626babb65e0", "type": "concept", "title": "contamination sequences"}, {"id": "1b9854b1-2017-47f0-b43c-6c452822c6bb", "type": "concept", "title": "agency and communion"}, {"id": "8576cb74-b1a6-4da7-a7ca-49b72a09c1f5", "type": "concept", "title": "life chapters"}], "description": "Students examine life stories as a level of personality."}]}, {"id": "7a805fa1-ccf8-4ccd-97a8-7a021edbb0d0", "type": "topic", "title": "Personality Development Across the Lifespan", "description": "Personality changes through development while also showing meaningful continuity, making lifespan evidence central to the field.", "children": [{"id": "cfbed4e0-b534-4a81-877d-2dc36c1bf9f5", "type": "subtopic", "title": "Childhood and temperament", "children": [{"id": "71dde553-f757-43e6-9e04-5a3ff8862cd0", "type": "concept", "title": "effortful control"}, {"id": "708a90d1-dab0-464c-8c61-7a2f29fae8a7", "type": "concept", "title": "attachment patterns"}, {"id": "711a1d87-66c7-46c1-b8aa-67f8f68ccac5", "type": "concept", "title": "parenting style"}, {"id": "f95dafe5-0c68-43a9-ba2e-655db3eca3d5", "type": "concept", "title": "differential susceptibility"}], "description": "Students learn how early temperament, attachment, and parenting relate to later personality."}, {"id": "63aa9cbf-833a-4e95-9587-a5533832dfd7", "type": "subtopic", "title": "Adolescence and emerging adulthood", "children": [{"id": "aab42565-3bcf-4111-b232-8da33ce0c3e4", "type": "concept", "title": "identity exploration"}, {"id": "d66a61eb-138b-4819-8adc-b6b2df9c5fe4", "type": "concept", "title": "rank-order stability"}, {"id": "fca1261a-1816-45f3-b9d2-3878f3ec8210", "type": "concept", "title": "mean-level change"}, {"id": "f757fa77-1379-4645-a91f-23826b3ae449", "type": "concept", "title": "social investment"}], "description": "Students examine identity, peer relationships, and maturation of traits."}, {"id": "1707c6b6-231a-490d-9154-e66bb3af2b42", "type": "subtopic", "title": "Adult development and aging", "children": [{"id": "399d2620-8e38-43a0-946d-3b5fade46404", "type": "concept", "title": "maturity principle"}, {"id": "2c5f5d6c-1577-4935-8e27-d0888b878313", "type": "concept", "title": "cumulative continuity"}, {"id": "b9c79117-a9f3-4bb9-8c8b-826a12dda827", "type": "concept", "title": "life transitions"}, {"id": "def78eab-c6b9-4d34-a63f-88fc2483d36d", "type": "concept", "title": "successful aging"}], "description": "Students study personality maturity and later-life change."}]}, {"id": "d044df23-43d5-4dd1-8bc5-fc87f9436bcb", "type": "topic", "title": "Personality Assessment and Psychometrics", "description": "A world-class personality course must teach students how personality is measured and why validity matters.", "children": [{"id": "4f849ff8-b0d0-4c46-ae32-ac74975387e7", "type": "subtopic", "title": "Assessment formats", "children": [{"id": "d700503b-8928-4260-903a-747c7be16ae2", "type": "concept", "title": "inventories"}, {"id": "60a7913a-286d-447c-9ada-ab4eeac48f8c", "type": "concept", "title": "observer ratings"}, {"id": "44777ca1-68b8-4eec-be95-a194eacaf46c", "type": "concept", "title": "structured interviews"}, {"id": "b783d59f-f1d7-4100-831c-d2f1611c03d6", "type": "concept", "title": "behavioral tasks"}], "description": "Students compare self-report, informant report, interview, behavioral, projective, and implicit methods."}, {"id": "4467492a-731e-4b14-bde4-a757a99da85f", "type": "subtopic", "title": "Reliability and validity", "children": [{"id": "b962e327-45fd-40e5-afda-6064718cba00", "type": "concept", "title": "internal consistency"}, {"id": "c8c4e4f3-71fa-4aec-8789-554ba91fc487", "type": "concept", "title": "test-retest reliability"}, {"id": "bc2e683d-4aff-4580-b79c-fc4cef78a55f", "type": "concept", "title": "construct validity"}, {"id": "3e5bb77b-21b7-4c56-bef0-d235bdea4fa0", "type": "concept", "title": "criterion validity"}], "description": "Students learn the technical standards that make scores interpretable."}, {"id": "ea3f4c61-0bb8-440e-a87f-f1d0203c51d0", "type": "subtopic", "title": "Test fairness and ethics", "children": [{"id": "a56c81fd-d033-4469-b01d-602e60ff3476", "type": "concept", "title": "test bias"}, {"id": "47f0bda3-109a-49e8-9bf8-80aa9c0adca6", "type": "concept", "title": "cultural fairness"}, {"id": "7d6b9b97-3e25-4336-8f1b-721d6340c22f", "type": "concept", "title": "informed consent"}, {"id": "9840fdac-e666-491c-ba2b-d7b105227115", "type": "concept", "title": "feedback and interpretation"}], "description": "Students learn how assessment can be useful, misused, biased, or harmful."}]}, {"id": "21656817-4c12-4e6f-8c72-17059151dbc7", "type": "topic", "title": "Culture, Gender, and Diversity in Personality", "description": "Students learn that personality universals and cultural variation must be studied together, with attention to power, language, and context.", "children": [{"id": "8f310bd8-0246-4c27-aa43-ab843d28e1ff", "type": "subtopic", "title": "Cross-cultural personality", "children": [{"id": "6b997d5f-dd8b-4ccc-88c2-7c378b7cc04c", "type": "concept", "title": "measurement equivalence"}, {"id": "b478860c-19bb-4c5c-b17a-21279b1fdeed", "type": "concept", "title": "etic and emic approaches"}, {"id": "cdff5178-4083-4ca4-bc6b-b9594dc48a2b", "type": "concept", "title": "cultural norms"}, {"id": "de53b436-f9a9-493b-83da-5a5183a2c1ea", "type": "concept", "title": "translation issues"}], "description": "Students examine what appears universal and what changes across cultural settings."}, {"id": "7914e3b4-68f8-4b78-983e-696178b31b30", "type": "subtopic", "title": "Gender and socialization", "children": [{"id": "82b443ee-54af-4ea5-85f8-3cef0d9d7166", "type": "concept", "title": "gender roles"}, {"id": "cc7612ff-1c94-419f-9173-22602d26fa0d", "type": "concept", "title": "stereotype threat"}, {"id": "0930446a-73f6-4a4c-a838-c9c747117873", "type": "concept", "title": "social expectations"}, {"id": "bf718fa3-20a7-422c-9cf7-5b745a0115c7", "type": "concept", "title": "intersectionality"}], "description": "Students separate biological, social, developmental, and measurement explanations for observed differences."}, {"id": "fc91ed8c-d033-4878-b9b7-144b2b0f4cf1", "type": "subtopic", "title": "Diversity and identity context", "children": [{"id": "11c90f4b-7166-430c-bc1e-535eaf58940a", "type": "concept", "title": "identity threat"}, {"id": "9d3275fb-d8ab-4fe4-89f0-0bdff050e467", "type": "concept", "title": "acculturation"}, {"id": "b5a0dfdd-14b5-4406-9e0e-9a47fa2e4a81", "type": "concept", "title": "minority stress"}, {"id": "dc0eef6f-b7e5-41aa-8755-a02262a612b5", "type": "concept", "title": "contextualized interpretation"}], "description": "Students analyze how race, class, culture, disability, sexuality, and migration can shape personality expression and assessment."}]}, {"id": "d0443067-ea02-41cd-8631-6fa3b76b26d2", "type": "topic", "title": "Personality in Social Relationships and Groups", "description": "Personality is expressed and shaped in relationships, groups, and social environments.", "children": [{"id": "02f39cb8-280f-4f77-b577-c0f1f264f7e8", "type": "subtopic", "title": "Interpersonal behavior", "children": [{"id": "449a2a18-e1b2-46f3-aa8f-2c1c79965f5b", "type": "concept", "title": "attachment"}, {"id": "69b7f271-107a-4740-bf2f-3cfa90865c7f", "type": "concept", "title": "trust"}, {"id": "fb07a170-b671-4793-9bdb-e02566925378", "type": "concept", "title": "empathy"}, {"id": "fe176d44-dd27-45f1-aeaa-4df0d0cf82c9", "type": "concept", "title": "conflict styles"}], "description": "Students connect traits and motives to relationship initiation, maintenance, and conflict."}, {"id": "9d36ecc7-305a-4311-80c3-1f9bb011e2e2", "type": "subtopic", "title": "Social cognition and attribution", "children": [{"id": "206a11ae-688d-4d8d-be6c-f9a4302f1db0", "type": "concept", "title": "attribution bias"}, {"id": "d0b7b341-3687-4679-887e-6451c3ecd1d1", "type": "concept", "title": "impression formation"}, {"id": "d16ec68e-b5ba-4274-abe1-dce8a7bdee37", "type": "concept", "title": "self-presentation"}, {"id": "ca21c8e0-0d70-4511-85bc-ed35ede05592", "type": "concept", "title": "social comparison"}], "description": "Students study how personality influences perception of self and others."}, {"id": "8e141969-2994-4d63-96a6-a785743bc115", "type": "subtopic", "title": "Groups and roles", "children": [{"id": "b4fa780a-a681-480a-a751-8705c6e612ed", "type": "concept", "title": "role identity"}, {"id": "d29b7c07-af3e-4a14-b2c5-8d499e5a33c2", "type": "concept", "title": "conformity"}, {"id": "e09cc150-a757-435b-840b-2a526a7e5632", "type": "concept", "title": "leadership emergence"}, {"id": "a5e2a851-ad40-4847-9d4d-a674a56882e5", "type": "concept", "title": "group norms"}], "description": "Students learn how groups amplify or constrain personality expression."}]}, {"id": "dd41353e-7568-44e0-a22d-27f1a633bfdf", "type": "topic", "title": "Personality, Health, Work, and Applied Life Outcomes", "description": "This unit shows how personality science informs real-world outcomes without turning traits into destiny.", "children": [{"id": "ca33052c-c249-4b89-bab8-79b4c5594345", "type": "subtopic", "title": "Health and well-being", "children": [{"id": "35154d9f-9551-45c4-b303-68b319e34ac4", "type": "concept", "title": "conscientiousness and health"}, {"id": "b9162718-6c40-4093-91be-a306e6f19bf1", "type": "concept", "title": "neuroticism and stress"}, {"id": "ce8af53c-cf75-40de-be98-624b5a7dfbac", "type": "concept", "title": "coping"}, {"id": "5d74c891-f03e-4300-a597-d30e6313ffde", "type": "concept", "title": "resilience"}], "description": "Students study links between traits, stress, health behavior, and longevity."}, {"id": "b6eeb8b2-2a65-4b2c-83f1-ca92078cd6a4", "type": "subtopic", "title": "Work and leadership", "children": [{"id": "394f810a-aa23-49e7-8027-c6fea7420bc2", "type": "concept", "title": "person-job fit"}, {"id": "cb377349-daf4-4ed9-a81b-f07c7ca457c4", "type": "concept", "title": "integrity"}, {"id": "2e8b3fdc-7212-4d87-a4e5-a31050139286", "type": "concept", "title": "leadership emergence"}, {"id": "7db20220-e00b-4fe1-9704-dbcb8e990a76", "type": "concept", "title": "counterproductive work behavior"}], "description": "Students connect personality to job performance, leadership, teamwork, and career fit."}, {"id": "c8baf378-a0f6-476c-906e-715cd327142a", "type": "subtopic", "title": "Education and life choices", "children": [{"id": "d3c173c1-bbba-4dd4-9214-4b4b400750ec", "type": "concept", "title": "grit debate"}, {"id": "4d7887aa-9f4b-4226-be0f-41b552f463f1", "type": "concept", "title": "self-control"}, {"id": "4e5ebd68-ef06-4ba6-8ab3-2fe810e19092", "type": "concept", "title": "major choice"}, {"id": "bea0ec91-03af-412b-917a-2b527df611fc", "type": "concept", "title": "achievement"}], "description": "Students examine how traits and goals shape educational pathways and decision-making."}]}, {"id": "5945942a-8ab2-4d43-b559-c5956b6f8437", "type": "topic", "title": "Personality Disorders and Maladaptive Personality", "description": "Students learn how normal-range traits connect to maladaptive patterns while avoiding stigma and simplistic labeling.", "children": [{"id": "be8cfbc5-1d4b-43b4-bdf0-8627f5d0ee00", "type": "subtopic", "title": "Trait models of pathology", "children": [{"id": "96f2f379-68dc-4330-b812-6538b3d8427f", "type": "concept", "title": "DSM-5-TR alternative model"}, {"id": "eda2ff13-66fd-49a0-99a2-0878eb8b0a93", "type": "concept", "title": "maladaptive trait domains"}, {"id": "e3886625-c21f-4aa7-a8ea-fece962eb706", "type": "concept", "title": "severity"}, {"id": "21b72053-377e-4c81-8779-cc0b9460745e", "type": "concept", "title": "impairment"}], "description": "Students connect dimensional personality models to clinical personality problems."}, {"id": "72ad55df-523e-49dd-8142-841cf5b4be73", "type": "subtopic", "title": "Major personality disorder patterns", "children": [{"id": "3d8df7dd-fb45-4117-a857-9b76c623d977", "type": "concept", "title": "borderline"}, {"id": "d00e2e90-bea5-4fc2-85fd-71bf6cd86202", "type": "concept", "title": "narcissistic"}, {"id": "6c93c20e-a71c-42e8-9ac0-d93e6600ae17", "type": "concept", "title": "avoidant"}, {"id": "6c90a04f-37b4-4247-abbc-4638a1251c76", "type": "concept", "title": "antisocial"}, {"id": "a119aa3d-5a9d-4025-982c-4a0254b043c7", "type": "concept", "title": "obsessive-compulsive personality"}], "description": "Students learn the gist of common diagnostic clusters and controversies."}, {"id": "7106d138-2913-402f-a6f6-2ad3388e47c4", "type": "subtopic", "title": "Assessment and ethics", "children": [{"id": "0cec0606-b010-